package com.rpb.reservation.workforce.scheduling.restswap;
import static com.rpb.reservation.workforce.scheduling.restswap.RestSwapDtos.*;
import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.core.namedparam.*;import org.springframework.stereotype.Repository;
@Repository
public class RestSwapRepository {
 private final JdbcTemplate jdbc;private final NamedParameterJdbcTemplate named;
 public RestSwapRepository(JdbcTemplate jdbc){this.jdbc=jdbc;named=new NamedParameterJdbcTemplate(jdbc);}
 public List<Link> list(UUID tenant,UUID store,LocalDate from,LocalDate to,UUID employee){return jdbc.query("select r.*,e.employee_no,e.name,case when s.deleted_at is not null then 'deleted' when s.work_date<>r.makeup_date or exists(select 1 from workforce_schedules occupied where occupied.tenant_id=r.tenant_id and occupied.employee_id=r.employee_id and occupied.work_date=r.rest_date and occupied.status='scheduled' and occupied.deleted_at is null) then 'changed' else s.status end makeup_status from workforce_rest_swaps r join workforce_employees e on e.id=r.employee_id and e.tenant_id=r.tenant_id join workforce_schedules s on s.id=r.makeup_schedule_id and s.tenant_id=r.tenant_id where r.tenant_id=? and r.store_id=? and (r.rest_date between ? and ? or r.makeup_date between ? and ?) and (?::uuid is null or r.employee_id=?::uuid) order by r.rest_date,e.employee_no,r.id",(r,n)->new Link(r.getObject("id",UUID.class),r.getObject("employee_id",UUID.class),r.getString("employee_no"),r.getString("name"),r.getObject("rest_date",LocalDate.class),r.getObject("makeup_date",LocalDate.class),r.getObject("makeup_schedule_id",UUID.class),r.getString("makeup_status")),tenant,store,from,to,from,to,employee,employee);}
 public List<Map<String,Object>> existing(UUID tenant,List<UUID> employees,LocalDate rest,LocalDate makeup){return named.queryForList("select id,employee_id,rest_date,makeup_date from workforce_rest_swaps where tenant_id=:tenant and employee_id in (:ids) and (rest_date in (:rest,:makeup) or makeup_date in (:rest,:makeup)) order by id",new MapSqlParameterSource("tenant",tenant).addValue("ids",employees).addValue("rest",rest).addValue("makeup",makeup));}
 public record Guard(UUID employeeId,String kind,UUID id,long version){}
 public List<Guard> guards(UUID tenant,List<UUID> employees,LocalDate rest,LocalDate makeup,ZoneId zone){var p=new MapSqlParameterSource("tenant",tenant).addValue("ids",employees).addValue("rest",rest).addValue("makeup",makeup).addValue("a",java.sql.Timestamp.from(rest.atStartOfDay(zone).toInstant())).addValue("b",java.sql.Timestamp.from(rest.plusDays(1).atStartOfDay(zone).toInstant())).addValue("c",java.sql.Timestamp.from(makeup.atStartOfDay(zone).toInstant())).addValue("d",java.sql.Timestamp.from(makeup.plusDays(1).atStartOfDay(zone).toInstant()));
 String dates="(s.work_date in (:rest,:makeup) or (x.%s<:b and coalesce(x.%s,'infinity'::timestamptz)>:a) or (x.%s<:d and coalesce(x.%s,'infinity'::timestamptz)>:c))";
 var rows=new ArrayList<Guard>();for(String kind:List.of("attendance","correction","leave")){String table=kind.equals("attendance")?"workforce_attendance_sessions":kind.equals("correction")?"workforce_corrections":"workforce_leaves",start=kind.equals("leave")?"start_at":"in_at",end=kind.equals("leave")?"end_at":"out_at",active=kind.equals("attendance")?"true":kind.equals("correction")?"x.status='pending'":"x.status in ('pending','approved','cancel_requested')";rows.addAll(named.query("select x.employee_id,x.id,x.version from "+table+" x join workforce_schedules s on s.tenant_id=x.tenant_id and s.id=x.schedule_id where x.tenant_id=:tenant and x.employee_id in (:ids) and "+active+" and "+dates.formatted(start,end,start,end)+" order by x.id",p,(r,n)->new Guard(r.getObject(1,UUID.class),kind,r.getObject(2,UUID.class),r.getLong(3))));}return rows;
 }
 public void save(UUID tenant,UUID store,UUID command,UUID employee,LocalDate rest,LocalDate makeup,UUID schedule,List<UUID> cancelled){jdbc.update("insert into workforce_rest_swaps(id,tenant_id,store_id,employee_id,rest_date,makeup_date,makeup_schedule_id,cancelled_schedule_ids,command_id) values(?,?,?,?,?,?,?,?::jsonb,?)",UUID.randomUUID(),tenant,store,employee,rest,makeup,schedule,"["+String.join(",",cancelled.stream().map(id->"\""+id+"\"").toList())+"]",command);}
}

